 void down(int id,float x,float y){float H=render.H;if(game.mode==MENU){if(hit(x,y,500,H*.43f,400,58))selectLevels();else if(hit(x,y,500,H*.43f+72,400,54)){release();game.mode=SETTINGS;}else if(hit(x,y,500,H*.43f+140,400,48))ANativeActivity_finish(app->activity);return;}if(game.mode==LEVELSELECT){if(hit(x,y,500,H-32,380,44)){menu();return;}float cell=(H-180)/2;for(int i=0;i<10;i++){float left=25+(i%5)*194,top=100+(i/5)*cell;if(hit(x,y,left+90,top+(cell-10)/2,180,cell-10)){startLevel(i);return;}}return;}
 if(game.mode==SETTINGS){if(hit(x,y,270,64,420,40)){game.editing=0;return;}if(hit(x,y,730,64,420,40)){game.editing=1;return;}if(hit(x,y,500,H-28,430,40)){menu();return;}if(hit(x,y,350,H-93,270,43)){game.terror=false;theme();save();return;}if(hit(x,y,690,H-93,270,43)){game.terror=true;theme();save();return;}float cell=(H-250)/2;for(int i=0;i<10;i++){float left=25+(i%5)*194,top=114+(i/5)*cell;if(hit(x,y,left+90,top+(cell-8)/2,180,cell-8)){game.choose(i);save();return;}}return;}if(game.mode==PAUSED){if(hit(x,y,500,H*.5f,360,64)){release();game.mode=PLAY;}else if(hit(x,y,500,H*.5f+82,360,52))menu();return;}if(game.mode==DEAD){if(hit(x,y,500,H*.47f,400,54))startLevel(game.level);else if(hit(x,y,500,H*.47f+66,400,50))selectLevels();else if(hit(x,y,500,H*.47f+128,360,46))menu();return;}if(game.mode==VICTORY){if(hit(x,y,500,H*.5f,440,60)){if(game.level<9)startLevel(game.level+1);else selectLevels();}else if(hit(x,y,500,H*.5f+82,360,52))menu();return;}
 if(near(x,y,955,43,38)){release();game.mode=PAUSED;return;}if(near(x,y,620,H-65,45)){game.switchWeapon();return;}if(near(x,y,740,H-65,49)){game.beginReload();return;}if(near(x,y,890,H-125,73)&&fireId<0){fireId=id;game.fireHeld=true;if(lookId<0){lookId=id;lookX=x;lookY=y;}return;}if(x<350&&y>H*.4f&&moveId<0){moveId=id;motion(id,x,y);return;}if(x>=350&&lookId<0){lookId=id;lookX=x;lookY=y;}}
